fn fibonacci(n: usize) -> Vec<i32> {
    // We assume n >= 2 and that all Fibonacci numbers up to F(n-1) fit in i32.
    let mut ret = Vec::with_capacity(n);
    // Base cases
    ret.push(0);
    ret.push(1);
    // Build the sequence iteratively
    for i in 2..n {
        let next = ret[i - 1] + ret[i - 2];
        ret.push(next);
    }
    ret
}

